// Default provider logos for billers, so a shop that has not uploaded its own still shows
// the right mark. These are the exact logos the shop owner uploaded to their own billers
// (see the wallet/biller brand chips); they are treated as the operator-supplied default set.
// A shop's own uploaded logo always wins over these.

export const PROVIDER_LOGOS: Record<string, string> = {
  "atom": "data:image/png;base64,",
  "mpt": "data:image/png;base64,",
  "mytel": "data:image/png;base64,",
  "u9": "data:image/jpeg;base64,",
};

// The provider keys, longest first so no key is a prefix of a mismatch.
const KEYS = Object.keys(PROVIDER_LOGOS).sort((a, b) => b.length - a.length);

/** The default logo for a biller name (ATOM, MPT, Mytel, U9...), or null. */
export function providerLogoFor(name: string): string | null {
  const n = (name || "").toLowerCase();
  for (const k of KEYS) {
    if (new RegExp("\\b" + k + "\\b").test(n)) return PROVIDER_LOGOS[k];
  }
  return null;
}
